// UpsertSessionInsight merges an incoming snapshot with any existing row
// keyed by (thread_id, local_turn_id). The update clause encodes two
// invariants the P3 plan requires at the SQL layer:
//
//   - terminal precedence: once status is 'interrupted' or 'aborted', a
//     later 'completed'/'failed' must not displace it. success is
//     likewise frozen once the locked terminal is set.
//   - token no-regression: counters only advance. A context-window-only
//     event with zero counts cannot regress token_input / token_output /
//     token_total. Each CASE guard is per-field so a legitimate zero
//     event for one dimension does not zero out a sibling.
//
// The *_observed flags go sticky: once TRUE, no later event can flip
// them back to FALSE. This keeps "we already saw real data" from being
// clobbered by a projection that doesn't re-emit the signal.
func (q *Queries) UpsertSessionInsight(ctx context.Context, arg UpsertSessionInsightParams) (UpsertSessionInsightRow, error) {
	row := q.db.QueryRowContext(ctx, upsertSessionInsight,
		arg.ThreadID,
		arg.AgentID,
		arg.SessionID,
		arg.Provider,
		arg.LocalTurnID,
		arg.ProviderTurnID,
		arg.StartedAt,
		arg.CompletedAt,
		arg.DurationMs,
		arg.Success,
		arg.Status,
		arg.StopReason,
		arg.ToolCalls,
		arg.ToolCallsObserved,
		arg.ToolFailures,
		arg.ToolFailuresObserved,
		arg.ApprovalRequests,
		arg.ApprovalRequestsObserved,
		arg.TokenInput,
		arg.TokenOutput,
		arg.TokenTotal,
		arg.TokenSnapshotObserved,
		arg.ContextWindowTokens,
		arg.UIProjection,
		arg.SkillsSelected,
		arg.CreatedAt,
		arg.UpdatedAt,
	)
	var i UpsertSessionInsightRow
	err := row.Scan(
		&i.ID,
		&i.ThreadID,
		&i.AgentID,
		&i.SessionID,
		&i.Provider,
		&i.LocalTurnID,
		&i.ProviderTurnID,
		&i.StartedAt,
		&i.CompletedAt,
		&i.DurationMs,
		&i.Success,
		&i.Status,
		&i.StopReason,
		&i.ToolCalls,
		&i.ToolCallsObserved,
		&i.ToolFailures,
		&i.ToolFailuresObserved,
		&i.ApprovalRequests,
		&i.ApprovalRequestsObserved,
		&i.TokenInput,
		&i.TokenOutput,
		&i.TokenTotal,
		&i.TokenSnapshotObserved,
		&i.ContextWindowTokens,
		&i.UIProjection,
		&i.SkillsSelected,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
